  ('equipment-ballistic-shields', 'ruleset-v5-core-curated-1', 'Ballistic Shields', 'INFANTRY_WEAPON', 'primary', 1, 0, 'experimental', 'The Store row 16', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":16,"sourceName":"Ballistic Shields","sourceSlot":"Primary","rulesText":"Heavy Energy or Physical shields made for Power Armor Troops capable of holding off substantial direct fire. Action: Shield Wall Unit is immoble and the effect ends when you move. Add +1 Armor when the full unit deploys shields in a wall formation against direct weapons. Does not Stack with any other Cover.","unitAccessText":"Power Armor","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-delayed-explosive-charge', 'ruleset-v5-core-curated-1', 'Delayed Explosive Charge', 'INFANTRY_WEAPON', 'secondary', 1, 0, 'experimental', 'The Store row 17', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":17,"sourceName":"Delayed Explosive Charge","sourceSlot":"Secondary","rulesText":"Can set explosves and then detonate remotely with an action. Uses FS for Damage. Special Forces comes with this equipment","unitAccessText":"Standard Infantry Orbital Drop Troopers Irregular Infantry Power Armor SF & Sappers","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
