  ('equipment-grab-handles-and-side-skirts', 'ruleset-v5-core-curated-1', 'Grab Handles and Side Skirts', 'VEHICLE_INTERNAL', 'internal', 1, 0, 'experimental', 'The Store row 48', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":48,"sourceName":"Grab handles & Side Skirts","sourceSlot":"Internal","rulesText":"For 1 turn an infantry unit can gab onto the sides of the vehicle and ride along. This is exhausting. So the infantry unit will need to rest a full round before doing it again. Hence the limit.","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-artillery-smoke-rounds', 'ruleset-v5-core-curated-1', 'Artillery Smoke Rounds', 'ARTILLERY_EQUIPMENT', 'ammo', 1, 0, 'experimental', 'The Store row 51', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":51,"sourceName":"Smoke Rounds (Artillery Only)","sourceSlot":"Ammo Type","rulesText":"Drop smoke on a hex. Blocks line of sight through and in indicated hex. Cooldown - 4 rounds","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
