  ('equipment-aerospace-hellfire-bombs', 'ruleset-v5-core-curated-1', 'Hellfire Bombs', 'AEROSPACE_ORDNANCE', 'bomb_bay', 1, 0, 'experimental', 'The Store row 87', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":87,"sourceName":"HellFire Bombs (Thanks Haven)","sourceSlot":"Bomb Bay","rulesText":"\"Drop Fire Bombs on 3 hex''s Burning it for till the start of the next round for base unit damage. Could be Area Denial. If they care about fire damage. Ignores armor given from building. Damage 2, Fly Over Range,","unitAccessText":"2 Per Crate","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
