  ('equipment-orbital-scanning-system', 'ruleset-v5-core-curated-1', 'Orbital Scanning System', 'SHIP_MODULE', 'external', 1, 0, 'experimental', 'The Store row 90', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":90,"sourceName":"Scanning System","sourceSlot":"External","rulesText":"Scan an area to reveal whats in the region. Pick a hex. Scans all connecting hex grids revealing for 1 round. Like all External equipment can be taken multiple times with each having its own cooldown.","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-orbital-rapid-fire-aa', 'ruleset-v5-core-curated-1', 'Rapid-fire Anti-air Cannons', 'SHIP_MODULE', 'external', 1, 0, 'experimental', 'The Store row 91', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":91,"sourceName":"Rapid Fire Anti-Air Cannons","sourceSlot":"External","rulesText":"Can attack 1 air unit per cannon. Can only Target Air Units.","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-orbital-rail-cannon', 'ruleset-v5-core-curated-1', 'Rail Cannon', 'SHIP_MODULE', 'external', 1, 0, 'experimental', 'The Store row 92', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":92,"sourceName":"Rail Cannon","sourceSlot":"External & Internal","rulesText":"A large high damage Magnetic Accelerator Cannon used to take down enemy orbitals and high armored targets on the surface. Uses up both an External and Internal Slot as the weapon uses up a large portion of the hull of the vessel. 10ap 5 damage shot on single hex. 3 round cooldown Can target ground and Orbital Targets.","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-orbital-bombardment-cannons', 'ruleset-v5-core-curated-1', 'Orbital Bombardment Cannons', 'SHIP_MODULE', 'external', 1, 0, 'experimental', 'The Store row 93', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":93,"sourceName":"Orbital Bombardment Cannons","sourceSlot":"External","rulesText":"4 cluster hex area is bombed per upgrade. Can only fire at ground targets. 2 Damage 2AP must be spread out Ground targets only","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-orbital-laser', 'ruleset-v5-core-curated-1', 'Orbital Laser', 'SHIP_MODULE', 'external', 1, 0, 'experimental', 'The Store row 94', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":94,"sourceName":"Orbital Laser","sourceSlot":"External","rulesText":"Single Hex Constant Damage Orbital Support Weapon. Used to target ground targets. Does 3 Damage every round for 3 rounds. Has 3AP","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-orbital-broadside-cannons', 'ruleset-v5-core-curated-1', 'Broadside Cannons', 'SHIP_MODULE', 'external', 1, 0, 'experimental', 'The Store row 95', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":95,"sourceName":"Broadside Cannon''s","sourceSlot":"External","rulesText":"Point blank anti-ship weapon system. Get close. Can Fire Every Turn","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-orbital-structure-drop', 'ruleset-v5-core-curated-1', 'Orbital Structure Drop', 'SHIP_MODULE', 'external', 1, 0, 'experimental', 'The Store row 96', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":96,"sourceName":"Orbital Structure Drop (Structure)","sourceSlot":"External","rulesText":"Halfs action time required by engineers to setup a structure. Does not work on roads or Airfields.","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-massive-cargo-bay', 'ruleset-v5-core-curated-1', 'Massive Cargo Bay', 'SHIP_MODULE', 'internal', 1, 0, 'experimental', 'The Store row 101', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":101,"sourceName":"Massive Cargo Bay","sourceSlot":"Internal","rulesText":"Works as an Unlimited Supply Point. Other units can pull supply from this vehicle. Aircraft and other units can rearm when landed on / in this orbital without using supply. Logi Craft can load supply from this orbital if they can land on it. Will not fit on Corvette sized Obitals. -2 Armor -5 FS from craft.","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-drop-pod-launch-bay', 'ruleset-v5-core-curated-1', 'Drop Pod Launch Bay', 'SHIP_MODULE', 'internal', 1, 0, 'experimental', 'The Store row 102', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":102,"sourceName":"Drop Pod Launch Bay","sourceSlot":"Internal","rulesText":"When in high orbit can launch loaded drop pods anywhere on the battlefield. When in low orbit can only fire pods inside the orbitals base range. Can load the drop pods with a veriety of equipment..... Once a Support pods list below is launched it takes time to load another. 4 Rounds. Drop troops can launch the round after they arrive onboard the drop. If you have the Armory Upgrade you can launch Infantry Supply Pods this pod offers a single reload of 1 weapon system for infantry. Limit 3 Total If you have Heavy Ground Bay you can Launch limited number of Vehicle Repair Supply Pods. This repair supply pod can be used by a vehicle unit to repair 2fs in the field with an action. Limit 3 Total. If you have the Engineer Bay you can drop Construction Supply pod. This holds an engineer contstuction supply reload. Reloading a single unit of engineers. Limit 3.","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-engineering-bay', 'ruleset-v5-core-curated-1', 'Engineering Bay', 'SHIP_MODULE', 'internal', 2, 0, 'experimental', 'The Store row 105', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":105,"sourceName":"Engineering Bay","sourceSlot":"Internal","rulesText":"If the Orbital has Orbital Structure Drop equipment the Engineers inside the engineering bay \"player unit\" can pre-build a portion or a full structure inside the Engineering bay before deployment. Only 1 Structure per Engineering Bay. Structure is built as normal. Deployed by orbital player.","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-landing-gear', 'ruleset-v5-core-curated-1', 'Landing Gear', 'SHIP_MODULE', 'internal', 1, 0, 'experimental', 'The Store row 106', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":106,"sourceName":"Landing Gear","sourceSlot":"Internal","rulesText":"Allows Corvette''s and only Corvette''s to land on the surface of a world. Great for Mech Bays or Ground Vehicle Bay''s","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-heavy-drop-pod-launch-bay', 'ruleset-v5-core-curated-1', 'Heavy Drop Pod Launch Bay', 'SHIP_MODULE', 'internal', 1, 0, 'experimental', 'The Store row 108', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":108,"sourceName":"Heavy Drop Pod Launch Bay","sourceSlot":"Internal","rulesText":"Can Drop large Heavy pods capable of landing Power Armor. Light Vehicles Light Mechs and light tanks. If you have the Engineering bay can drop Heavy Automated Turret Pods.","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-reinforced-structural-integrity', 'ruleset-v5-core-curated-1', 'Reinforced Structural Integrity', 'SHIP_MODULE', 'internal', 1, 0, 'experimental', 'The Store row 109', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":109,"sourceName":"Reinforced Structural Integrity","sourceSlot":"Internal","rulesText":"Add +2 to FS of the Orbital per upgrade (limited 2 for now)","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-orbital-thrusters', 'ruleset-v5-core-curated-1', 'Orbital Thrusters Upgrade', 'SHIP_MODULE', 'internal', 2, 0, 'experimental', 'The Store row 110', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":110,"sourceName":"Orbital Thrusters Upgrade Can only be taken onces","sourceSlot":"Internal","rulesText":"Time to High Orbit -1 Round","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}'),
  ('equipment-through-ship-interior-hangar', 'ruleset-v5-core-curated-1', 'Through-ship Interior Hangar', 'SHIP_MODULE', 'internal', 1, 0, 'experimental', 'The Store row 112', 'Source-exact catalogue entry; execution remains gated until its effect handler is implemented.', '{"storeCatalogue":{"storeRow":112,"sourceName":"Through Ship Interior Hanger Destoryer or Larger only","sourceSlot":"Internal","rulesText":"Allows the landing and storage of a single Aerospace unit per Interior hanger. - 2 Armor from Craft to a minimum of 1","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}')
ON CONFLICT(id, ruleset_id) DO UPDATE SET
  name = excluded.name, category = excluded.category, slot_type = excluded.slot_type,
  requisition_cost = excluded.requisition_cost, consumable = excluded.consumable,
  definition_status = excluded.definition_status, source = excluded.source,
  notes = excluded.notes, definition_json = excluded.definition_json;

UPDATE equipment_definitions
SET definition_json = json_patch(definition_json, '{"storeCatalogue":{"storeRow":2,"sourceName":"Melee Weapons- Standard","sourceSlot":"Primary","rulesText":"Action - Melee Charge: \"Charge into an enemy line starting a melee brawl. When fighting in a brawl no range units can fire at either side due to the danger of hitting friendly forces. Units with melee options or infantry equipped with sniper rifles can join in the fight safely.\" If you have melee weapons and are flanked you can choose to stand and fight.","unitAccessText":"All Infantry Other than Irregular''s","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}')
WHERE id = 'equipment-standard-melee-weapons' AND ruleset_id = 'ruleset-v5-core-curated-1';

