WHERE id = 'equipment-mech-bay' AND ruleset_id = 'ruleset-v5-core-curated-1';

UPDATE equipment_definitions
SET definition_json = json_patch(definition_json, '{"storeCatalogue":{"storeRow":101,"sourceName":"Massive Cargo Bay","sourceSlot":"Internal","rulesText":"Works as an Unlimited Supply Point. Other units can pull supply from this vehicle. Aircraft and other units can rearm when landed on / in this orbital without using supply. Logi Craft can load supply from this orbital if they can land on it. Will not fit on Corvette sized Obitals. -2 Armor -5 FS from craft.","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}')
WHERE id = 'equipment-massive-cargo-bay' AND ruleset_id = 'ruleset-v5-core-curated-1';

UPDATE equipment_definitions
SET definition_json = json_patch(definition_json, '{"storeCatalogue":{"storeRow":102,"sourceName":"Drop Pod Launch Bay","sourceSlot":"Internal","rulesText":"When in high orbit can launch loaded drop pods anywhere on the battlefield. When in low orbit can only fire pods inside the orbitals base range. Can load the drop pods with a veriety of equipment..... Once a Support pods list below is launched it takes time to load another. 4 Rounds. Drop troops can launch the round after they arrive onboard the drop. If you have the Armory Upgrade you can launch Infantry Supply Pods this pod offers a single reload of 1 weapon system for infantry. Limit 3 Total If you have Heavy Ground Bay you can Launch limited number of Vehicle Repair Supply Pods. This repair supply pod can be used by a vehicle unit to repair 2fs in the field with an action. Limit 3 Total. If you have the Engineer Bay you can drop Construction Supply pod. This holds an engineer contstuction supply reload. Reloading a single unit of engineers. Limit 3.","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}')
WHERE id = 'equipment-drop-pod-launch-bay' AND ruleset_id = 'ruleset-v5-core-curated-1';

UPDATE equipment_definitions
SET definition_json = json_patch(definition_json, '{"storeCatalogue":{"storeRow":103,"sourceName":"\"Mobile Infantry Upgrade (needs attached infantry player declared before campaign start)\"","sourceSlot":"External & Internal","rulesText":"\"Allows 2 Units of Infantry to live on the ship. Comes with Dedicated shuttle for picking up and dropping off attached infantry in range of the ship. --Action - Deploy all Infantry: Deploys Units assigned to this battlegroup inside the ships range using the dedicated short-range landing craft stored in the ship. These shuttles take time to refuel. 6 Round cooldown. ---Action - Recover all Infantry: Recovers all infantry assigned to this battlegroup inside the ships range back to the vessel in a orderly fashion. 6 Round Cooldown.\"","unitAccessText":"","effectStatus":"SEE_IMPLEMENTATION_OVERLAY"}}')
WHERE id = 'equipment-mobile-infantry' AND ruleset_id = 'ruleset-v5-core-curated-1';

UPDATE equipment_definitions
SET definition_json = json_patch(definition_json, '{"storeCatalogue":{"storeRow":104,"sourceName":"Armory","sourceSlot":"Internal","rulesText":"Increase enemy boarders take over time +2 Intracts with Drop Pods Supply point for attached infantry and allows them to change equipment if owned. Infantry Reloading here uses 1 Supply per weapon system","unitAccessText":"","effectStatus":"SEE_IMPLEMENTATION_OVERLAY"}}')
WHERE id = 'equipment-armory' AND ruleset_id = 'ruleset-v5-core-curated-1';

UPDATE equipment_definitions
SET definition_json = json_patch(definition_json, '{"storeCatalogue":{"storeRow":105,"sourceName":"Engineering Bay","sourceSlot":"Internal","rulesText":"If the Orbital has Orbital Structure Drop equipment the Engineers inside the engineering bay \"player unit\" can pre-build a portion or a full structure inside the Engineering bay before deployment. Only 1 Structure per Engineering Bay. Structure is built as normal. Deployed by orbital player.","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}')
WHERE id = 'equipment-engineering-bay' AND ruleset_id = 'ruleset-v5-core-curated-1';

UPDATE equipment_definitions
SET definition_json = json_patch(definition_json, '{"storeCatalogue":{"storeRow":106,"sourceName":"Landing Gear","sourceSlot":"Internal","rulesText":"Allows Corvette''s and only Corvette''s to land on the surface of a world. Great for Mech Bays or Ground Vehicle Bay''s","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}')
WHERE id = 'equipment-landing-gear' AND ruleset_id = 'ruleset-v5-core-curated-1';

UPDATE equipment_definitions
SET definition_json = json_patch(definition_json, '{"storeCatalogue":{"storeRow":107,"sourceName":"Heavy Ground Vehicle Bay","sourceSlot":"Internal","rulesText":"Allows 2 Units of Armor, or 1 Super Heavy to live on the ship. Comes with Dedicated Large Ramp for picking up and dropping off Armor if the Orbital can land \"corvette only\". Bay repairs ground vehicles at 1FS pre turn that are inside. While the bay can repair Heavy Artillery, Armor and Light vehicles. It can''t repair Mechs.","unitAccessText":"","effectStatus":"SEE_IMPLEMENTATION_OVERLAY"}}')
WHERE id = 'equipment-heavy-ground-vehicle-bay' AND ruleset_id = 'ruleset-v5-core-curated-1';

UPDATE equipment_definitions
SET definition_json = json_patch(definition_json, '{"storeCatalogue":{"storeRow":108,"sourceName":"Heavy Drop Pod Launch Bay","sourceSlot":"Internal","rulesText":"Can Drop large Heavy pods capable of landing Power Armor. Light Vehicles Light Mechs and light tanks. If you have the Engineering bay can drop Heavy Automated Turret Pods.","unitAccessText":"","effectStatus":"SOURCE_EXACT_HANDLER_DEFERRED"}}')
