WHERE id = 'equipment-orbital-thrusters' AND ruleset_id = 'ruleset-v5-core-curated-1';

UPDATE equipment_definitions
SET definition_json = json_patch(definition_json, '{"storeCatalogue":{"storeRow":111,"sourceName":"Aerospace Storage Hanger Destoryer or Larger only","sourceSlot":"Internal","rulesText":"Allows the storage and reloading of a aerospace unit per Interior hanger.-1 FS per Aerospace Storage Hanger. This is not a landing pad. Its built inside the ship. Inceases Cargo Capactiy +4 per Hanger You need a place for ships to land before they can be stored!","unitAccessText":"","effectStatus":"SEE_IMPLEMENTATION_OVERLAY"}}')
